import { stegaClean } from 'next-sanity'

import { HeroEditorial } from './editorial'
import { HeroFullBleed } from './full-bleed'
import { HeroOverlay } from './overlay'
import { HeroSplit } from './split'
import type { SectionProps } from '../../../types'

/**
 * `data` is SectionOf<'hero'>: the exact projection of `heroFragment`, generated by TypeGen.
 * Every variant renders the same data; the `variant` field (schema: HERO_VARIANTS) picks the layout.
 * Content with no variant, or one this deployment doesn't know, gets the default (overlay).
 */
export function Hero(props: SectionProps<'hero'>) {
  switch (stegaClean(props.data.variant)) {
    case 'split':
      return <HeroSplit {...props} />
    case 'editorial':
      return <HeroEditorial {...props} />
    case 'full-bleed':
      return <HeroFullBleed {...props} />
    default:
      return <HeroOverlay {...props} />
  }
}
